const BASE = import.meta.env.BASE_URL ?? '/'

/**
 * Placeholder assets generated by tools/generate_sample_assets.py.
 * They are a mannequin and a T-shirt shape, NOT a body scan and NOT a fit simulation.
 */
export const SAMPLE_ASSETS = {
  avatar: { url: `${BASE}models/avatar.glb`, label: 'Sample mannequin' },
  garment: { url: `${BASE}models/garment.glb`, label: 'Sample T-shirt' },
}

/** Only same-origin absolute paths to .glb files are accepted from the query string. */
export function isSafeAssetOverride(value) {
  return (
    typeof value === 'string' &&
    value.length > 0 &&
    value.length <= 200 &&
    value.startsWith('/') &&
    !value.startsWith('//') &&
    !value.includes('\\') &&
    !value.includes('..') &&
    value.toLowerCase().endsWith('.glb')
  )
}

/**
 * Development / test hook: `?avatar=/models/other.glb`, `?garment=/models/other.glb` or
 * `?garment=none`. Used to exercise missing-asset states. Unsafe values are ignored.
 */
export function resolveAssetUrls(search = '') {
  const params = new URLSearchParams(search)
  const avatar = params.get('avatar')
  const garment = params.get('garment')
  return {
    avatarUrl: isSafeAssetOverride(avatar) ? avatar : SAMPLE_ASSETS.avatar.url,
    garmentUrl:
      garment === 'none'
        ? null
        : isSafeAssetOverride(garment)
          ? garment
          : SAMPLE_ASSETS.garment.url,
  }
}
